from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import sqlite3
import tempfile
import unittest
from unittest.mock import patch

import config
import uniclubs_database
import uniclubs_export


NOW = datetime(2026, 11, 15, 17, 0, tzinfo=timezone.utc)
NEXT = NOW + timedelta(hours=1)
STAMP = '2026-11-15T17:00:00.000000Z'
CLUB_URL = 'https://uniclubs.ch/hsg/clubs/example-club'
EVENT_URL = CLUB_URL + '/events/example-event'
EVENT_FIELDS = {
    'id', 'external_id', 'club_id', 'title', 'start_utc', 'end_utc', 'location',
    'event_type', 'source_url', 'publication_status', 'availability_state',
    'requires_membership', 'first_seen_utc', 'last_seen_utc', 'source_missing',
}


def table_snapshot(connection):
    """Read all catalog data using fixed SQL to detect unintended partial writes."""
    clubs = connection.execute('SELECT * FROM clubs ORDER BY id').fetchall()
    events = connection.execute('SELECT * FROM events ORDER BY id').fetchall()
    logs = connection.execute('SELECT * FROM import_log ORDER BY id').fetchall()
    return ([tuple(row) for row in clubs], [tuple(row) for row in events],
            [tuple(row) for row in logs])


class UniClubsExportTests(unittest.TestCase):
    """Keep public export state distinct from private application data and import history."""

    def setUp(self):
        """Create a fictional catalog with nonconsecutive IDs, history and a missing source."""
        self.connection = self.empty_catalog()
        with self.connection:
            self.connection.execute('''INSERT INTO clubs (id, external_id, name, source_url)
                VALUES (?, ?, ?, ?)''', (7, 'club-1', 'Zürich Club', CLUB_URL))
            self.connection.execute('''INSERT INTO clubs (id, external_id, name, source_url)
                VALUES (?, ?, ?, ?)''',
                                    (19, 'club-unused', 'Other Club', CLUB_URL + '-other'))
        first = {
            'external_id': 'event-past', 'club_id': 7, 'title': 'Zürich workshop',
            'start_utc': '2026-11-14T11:00:00Z', 'end_utc': '2026-11-14T12:00:00Z',
            'source_url': EVENT_URL, 'requires_membership': True,
            'publication_status': 'published', 'availability_state': 'sales_closed',
        }
        uniclubs_database.add_event(self.connection, first, now=NOW)
        with self.connection:
            self.connection.execute('''UPDATE events SET id=?, source_missing=?
                WHERE external_id=?''', (37, 1, 'event-past'))
        second = dict(first)
        second.update(external_id='event-future', title='Future workshop',
                      start_utc='2026-11-16T11:00:00Z', end_utc=None,
                      source_url=EVENT_URL + '-future', requires_membership=None)
        uniclubs_database.add_event(self.connection, second, now=NOW)
        uniclubs_database.record_import(self.connection, 'success', 2,
                                       message='Public success report.', now=NOW)

    def empty_catalog(self):
        """Return an independent empty in-memory catalog that the test closes automatically."""
        connection = uniclubs_database.get_connection(':memory:')
        self.addCleanup(connection.close)
        uniclubs_database.init_db(connection)
        return connection

    def payload(self):
        """Return a fresh valid export that individual validation tests can mutate."""
        return uniclubs_export.build_export(self.connection)

    def test_only_explicit_public_fields_are_exported(self):
        """Extra database columns and import log messages must never leak into the snapshot."""
        with self.connection:
            self.connection.execute('ALTER TABLE events ADD COLUMN private_note TEXT')
            self.connection.execute('UPDATE events SET private_note=?', ('private-marker',))
        document = self.payload()
        self.assertEqual(set(document), {'_meta', 'clubs', 'events'})
        self.assertEqual(set(document['clubs'][0]), {'id', 'external_id', 'name', 'source_url'})
        self.assertTrue(all(set(event) == EVENT_FIELDS for event in document['events']))
        text = json.dumps(document)
        self.assertNotIn('private_note', text)
        self.assertNotIn('private-marker', text)
        self.assertNotIn('Public success report.', text)
        self.assertNotIn('import_log', document)

    def test_latest_success_is_used_and_a_successful_snapshot_is_required(self):
        """A later failure must neither advance export freshness nor replace a valid result."""
        uniclubs_database.record_import(self.connection, 'error',
                                       message='Private transport marker.', now=NEXT)
        document = self.payload()
        self.assertEqual(document['_meta']['last_success_utc'], STAMP)
        self.assertNotIn('Private transport marker.', json.dumps(document))
        with self.connection:
            self.connection.execute("DELETE FROM import_log WHERE status='success'")
        with self.assertRaises(ValueError):
            self.payload()

    def test_json_writes_are_deterministic_and_preserve_utf8(self):
        """Writing the same successful catalog twice must produce identical valid JSON bytes."""
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / 'nested' / 'snapshot.json'
            first = uniclubs_export.write_export(self.connection, path)
            original = path.read_bytes()
            second = uniclubs_export.write_export(self.connection, path)
            self.assertEqual(path.read_bytes(), original)
            self.assertEqual(first, second)
            self.assertEqual(json.loads(path.read_text(encoding='utf-8')), first)
            self.assertIn('Zürich', path.read_text(encoding='utf-8'))
            self.assertTrue(original.endswith(b'\n'))

    def test_roundtrip_preserves_local_ids_source_ids_and_observation_times(self):
        """A fresh runner must rebuild exactly the public state instead of renumbering it."""
        original = self.payload()
        restored = self.empty_catalog()
        uniclubs_export.restore_export(restored, original)
        result = uniclubs_export.build_export(restored)
        self.assertEqual(result, original)
        self.assertEqual([club['id'] for club in result['clubs']], [7, 19])
        self.assertEqual(result['events'][0]['id'], 37)
        self.assertEqual(result['events'][0]['first_seen_utc'], STAMP)
        logs = uniclubs_database.get_import_log(restored)
        self.assertEqual(len(logs), 1)
        self.assertEqual(logs[0]['status'], 'success')
        self.assertEqual(logs[0]['imported_at_utc'], STAMP)

    def test_past_missing_and_unknown_metadata_survive_restoration(self):
        """Snapshots must retain old identities, missing markers and genuinely unknown values."""
        document = self.payload()
        self.assertEqual(len(document['events']), 2)
        self.assertTrue(document['events'][0]['source_missing'])
        self.assertTrue(document['events'][0]['requires_membership'])
        self.assertIsNone(document['events'][1]['end_utc'])
        self.assertIsNone(document['events'][1]['requires_membership'])
        restored = self.empty_catalog()
        uniclubs_export.restore_export(restored, document)
        rows = uniclubs_database.get_events(restored)
        self.assertEqual(rows[0]['external_id'], 'event-past')
        self.assertEqual(rows[0]['source_missing'], 1)
        self.assertEqual(rows[0]['availability_state'], 'sales_closed')

    def test_invalid_envelopes_and_metadata_are_rejected(self):
        """Reject incompatible schemas and incorrect snapshot provenance before restoration."""
        candidates = [None, [], {'_meta': {}}, self.payload(), self.payload(), self.payload()]
        candidates[3]['_meta']['schema_version'] = True
        candidates[4]['_meta']['schema_version'] = 2
        candidates[5]['_meta']['source_url'] = 'https://other.example/events'
        for document in candidates:
            with self.subTest(document=document):
                with self.assertRaises(ValueError):
                    uniclubs_export.validate_export(document)

    def test_missing_event_can_retain_old_link_after_club_slug_changes(self):
        """A club rename must not make its retained missing event impossible to publish."""
        renamed = 'https://uniclubs.ch/hsg/clubs/renamed-club'
        with self.connection:
            self.connection.execute('UPDATE clubs SET source_url=? WHERE id=?', (renamed, 7))
            self.connection.execute('UPDATE events SET source_url=? WHERE external_id=?',
                                    (renamed + '/events/future', 'event-future'))
        document = self.payload()
        restored = self.empty_catalog()
        uniclubs_export.restore_export(restored, document)
        rows = uniclubs_database.get_events(restored)
        self.assertEqual(rows[0]['source_url'], EVENT_URL)
        self.assertEqual(rows[0]['source_missing'], 1)
        self.assertEqual(uniclubs_export.build_export(restored), document)

    def test_duplicate_local_or_external_ids_are_rejected(self):
        """Distinct rows may never silently overwrite one another during restoration."""
        for table, field in (('clubs', 'id'), ('clubs', 'external_id'),
                             ('events', 'id'), ('events', 'external_id')):
            document = self.payload()
            document[table][1][field] = document[table][0][field]
            with self.subTest(table=table, field=field):
                with self.assertRaises(ValueError):
                    uniclubs_export.validate_export(document)

    def test_orphan_event_and_late_malformed_row_do_not_create_partial_state(self):
        """Validate all rows before inserting any part of a damaged public snapshot."""
        for changes in ({'club_id': 999}, {'title': ''}):
            document = self.payload()
            document['events'][1].update(changes)
            restored = self.empty_catalog()
            with self.subTest(changes=changes):
                with self.assertRaises(ValueError):
                    uniclubs_export.restore_export(restored, document)
                self.assertEqual(table_snapshot(restored), ([], [], []))

    def test_invalid_event_or_observation_time_order_is_rejected(self):
        """Reject invalid UTC instants and impossible event or snapshot observation ordering."""
        candidates = [
            ('start_utc', 'not-a-time'),
            ('end_utc', '2026-11-14T11:00:00.000000Z'),
            ('first_seen_utc', '2026-11-15T18:00:00.000000Z'),
            ('last_seen_utc', '2026-11-15T18:00:00.000000Z'),
        ]
        for field, value in candidates:
            document = self.payload()
            document['events'][0][field] = value
            with self.subTest(field=field):
                with self.assertRaises(ValueError):
                    uniclubs_export.validate_export(document)

    def test_boolean_flags_and_local_ids_use_distinct_types(self):
        """Do not accept strings or integers as JSON booleans, or booleans as local IDs."""
        for field, value in (('requires_membership', 'yes'), ('requires_membership', 1),
                             ('source_missing', 1), ('id', True), ('club_id', True)):
            document = self.payload()
            document['events'][0][field] = value
            with self.subTest(field=field, value=value):
                with self.assertRaises(ValueError):
                    uniclubs_export.validate_export(document)

    def test_source_links_reject_other_hosts_credentials_and_secret_query_strings(self):
        """The public feed must not carry arbitrary external or credential-bearing URLs."""
        urls = [
            'http://uniclubs.ch/hsg/clubs/example-club',
            'https://other.example/hsg/clubs/example-club',
            'https://user:password@uniclubs.ch/hsg/clubs/example-club',
            CLUB_URL + '?token=secret',
            CLUB_URL + '#private-fragment',
        ]
        for table in ('clubs', 'events'):
            for url in urls:
                document = self.payload()
                document[table][0]['source_url'] = url
                with self.subTest(table=table, url=url):
                    with self.assertRaises(ValueError):
                        uniclubs_export.validate_export(document)

    def test_record_limit_bounds_snapshot_validation(self):
        """A retained catalog still needs a finite import size limit on a fresh runner."""
        document = self.payload()
        with patch.object(config, 'UNICLUBS_MAX_EXPORT_RECORDS', 1):
            with self.assertRaises(ValueError):
                uniclubs_export.validate_export(document)

    def test_restoration_refuses_existing_catalog_without_overwriting_it(self):
        """Loading a snapshot must never erase a populated catalog or its import history."""
        original = table_snapshot(self.connection)
        with self.assertRaises(ValueError):
            uniclubs_export.restore_export(self.connection, self.payload())
        self.assertEqual(table_snapshot(self.connection), original)

    def test_restoration_preserves_an_open_caller_transaction(self):
        """Refuse pending writes before entering any rollback-capable transaction context."""
        restored = self.empty_catalog()
        restored.execute('''INSERT INTO clubs (external_id, name, source_url)
            VALUES (?, ?, ?)''', ('pending', 'Pending Club', CLUB_URL))
        with self.assertRaises(ValueError):
            uniclubs_export.restore_export(restored, self.payload())
        self.assertTrue(restored.in_transaction)
        self.assertEqual(restored.execute('SELECT count(*) FROM clubs').fetchone()[0], 1)

    def test_late_sql_failure_rolls_back_the_whole_restoration(self):
        """A real insert failure after earlier rows must leave no clubs, events or success log."""
        restored = self.empty_catalog()
        with restored:
            restored.execute('''CREATE TRIGGER reject_second_event BEFORE INSERT ON events
                WHEN NEW.external_id='event-future'
                BEGIN SELECT RAISE(ABORT, 'Controlled test failure'); END''')
        with self.assertRaises(sqlite3.IntegrityError):
            uniclubs_export.restore_export(restored, self.payload())
        self.assertEqual(table_snapshot(restored), ([], [], []))

    def test_failed_atomic_replace_preserves_previous_export_and_cleans_temporary_file(self):
        """A filesystem failure must retain the last published JSON instead of truncating it."""
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / 'snapshot.json'
            original = b'Previous successful snapshot\n'
            path.write_bytes(original)
            with patch.object(Path, 'replace', side_effect=OSError('Controlled replace failure')):
                with self.assertRaises(OSError):
                    uniclubs_export.write_export(self.connection, path)
            self.assertEqual(path.read_bytes(), original)
            self.assertEqual({item.name for item in Path(folder).iterdir()}, {'snapshot.json'})

    def test_export_path_cannot_replace_either_database(self):
        """Output path checks protect database files even when explicitly passed by mistake."""
        with tempfile.TemporaryDirectory() as folder:
            old_db = Path(folder) / 'old.sqlite'
            new_db = Path(folder) / 'new.sqlite'
            for path in (old_db, new_db):
                path.write_bytes(b'Original database placeholder')
            with patch.object(config, 'DB_FILE', old_db):
                with patch.object(config, 'UNICLUBS_DB_FILE', new_db):
                    for path in (old_db, new_db):
                        with self.subTest(path=path):
                            with self.assertRaises(ValueError):
                                uniclubs_export.write_export(self.connection, path)
            for path in (old_db, new_db):
                self.assertEqual(path.read_bytes(), b'Original database placeholder')

    def test_successful_empty_catalog_can_roundtrip_without_becoming_an_error(self):
        """A verified empty result differs from a missing or malformed snapshot document."""
        empty = self.empty_catalog()
        uniclubs_database.record_import(empty, 'success', 0, now=NOW)
        document = uniclubs_export.build_export(empty)
        self.assertEqual(document['clubs'], [])
        self.assertEqual(document['events'], [])
        restored = self.empty_catalog()
        uniclubs_export.restore_export(restored, document)
        self.assertEqual(uniclubs_export.build_export(restored), document)

    def test_sqlite_export_roundtrips_and_excludes_private_fields(self):
        """A fresh file contains exactly public fields, including flags and unknown values."""
        with self.connection:
            self.connection.execute('ALTER TABLE events ADD COLUMN private_note TEXT')
            self.connection.execute('UPDATE events SET private_note=?', ('private-marker',))
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / 'nested' / 'catalog.sqlite'
            uniclubs_export.write_sqlite(self.connection, path)
            exported = uniclubs_database.get_connection(path)
            try:
                self.assertEqual(uniclubs_export.build_export(exported), self.payload())
                self.assertEqual(exported.execute('PRAGMA integrity_check').fetchone()[0], 'ok')
                self.assertEqual(exported.execute('PRAGMA foreign_key_check').fetchall(), [])
                names = {row[0] for row in exported.execute(
                              "SELECT name FROM sqlite_master WHERE type='table'")}
                self.assertEqual(names, {'clubs', 'events', 'import_log'})
                self.assertEqual(path.read_bytes().find(b'private'), -1)
            finally:
                exported.close()

    def test_sqlite_export_is_repeatable(self):
        """Replacing a successful file twice preserves all identities and observations."""
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / 'catalog.sqlite'
            uniclubs_export.write_sqlite(self.connection, path)
            original = path.read_bytes()
            uniclubs_export.write_sqlite(self.connection, path)
            self.assertEqual(path.read_bytes(), original)

    def test_sqlite_replace_failure_leaves_old_file(self):
        """An unsuccessful write keeps the previous file and cleans temporary files."""
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / 'catalog.sqlite'
            original = b'previous'
            path.write_bytes(original)
            with patch.object(Path, 'replace', side_effect=OSError):
                with self.assertRaises(OSError):
                    uniclubs_export.write_sqlite(self.connection, path)
            self.assertEqual(path.read_bytes(), original)
            self.assertEqual(list(Path(folder).iterdir()), [path])

    def test_sqlite_export_rejects_active_paths(self):
        """Source files and application databases are protected from replacement."""
        with tempfile.TemporaryDirectory() as folder:
            source = Path(folder) / 'source'
            active = uniclubs_database.get_connection(source)
            try:
                with self.assertRaises(ValueError):
                    uniclubs_export.write_sqlite(active, source)
            finally:
                active.close()

    def test_sqlite_export_rejects_transaction(self):
        """Pending writes survive rejection."""
        self.connection.execute('DELETE FROM events')
        with tempfile.TemporaryDirectory() as folder:
            with self.assertRaises(ValueError):
                uniclubs_export.write_sqlite(self.connection, Path(folder))
            self.assertTrue(self.connection.in_transaction)


if __name__ == '__main__':
    unittest.main()
